// src/components/dashboard/DashboardLayoutClient.tsx
'use client';

import { ReactNode } from 'react';
import {
  Home, Layers, User, Settings, Bell, Maximize2, Minimize2, Pin, X, PlusCircle,
} from 'lucide-react';
import type { Tenant } from '@prisma/client'; // Assuming this path is correct

import BaseDashboardLayout, {
  NavItem,
  DashboardCard as BaseDashboardCard,
  Notification as BaseNotification,
  RenderMainContentParams,
} from './BaseDashboardLayout';

// Import QuickBoard and its types/plugins
import OriginalQuickBoardComponent from './quickboard/QuickBoardComponent';
import { QuickBoardPlugin } from './quickboard/types'; // Import the QuickBoardPlugin interface

// --- IMPORT YOUR QUICKBOARD PLUGINS ---
import UserCountQuickBoardPlugin from './quickboard/plugins/UserCountQuickBoardPlugin';
import ManyChatControlQuickBoardPlugin from './quickboard/plugins/ManyChatControlQuickBoardPlugin';
// import SupplierOverviewPlugin from './quickboard/plugins/SupplierOverviewPlugin'; // If you have this

// Placeholder for SupplierOverviewPlugin if not fully implemented yet
const SupplierOverviewPlugin: React.FC<{showCustomModal?: any}> = ({showCustomModal}) => (
  <div>Placeholder for Supplier Overview. {showCustomModal && <button onClick={() => showCustomModal("Detail from Supplier", "Supplier Detail")}>Details</button>}</div>
);


interface DashboardLayoutClientProps {
  tenant: Tenant;
  initialDashboardContent: ReactNode;
}

export default function DashboardLayoutClient({
  tenant,
  initialDashboardContent,
}: DashboardLayoutClientProps) {
  const tenantType = 'client';

  const navItems: NavItem[] = [
    { icon: <Home size={20} />, title: 'Overview' },
    { icon: <Layers size={20} />, title: 'Main Board' },
    { icon: <Layers size={20} />, title: 'Quick Board' }, // Our target
    { icon: <User size={20} />, title: 'My Account' },
    { icon: <Bell size={20} />, title: 'Notifications' },
    { icon: <Settings size={20} />, title: 'Settings' },
  ];

  const clientDashboardCards: BaseDashboardCard[] = [
    // ... your cards
    { id: 'client-card-1', title: 'Global Analytics', color: 'bg-blue-100' },
    { id: 'client-card-2', title: 'Team Tasks', color: 'bg-green-100' },
  ];

  const initialNotifications: BaseNotification[] = [
    // ... your notifications
    { id: 'client-notif-1', text: `Welcome to ${tenant.name}'s client dashboard!`, read: false, timestamp: new Date().toISOString() },
  ];

  // --- DEFINE USER ROLES (Replace with actual logic) ---
  const getCurrentUserRoles = (): string[] => {
    // In a real app, get this from auth context, user state, etc.
    // For testing, you can cycle roles or set them statically.
    // return ['admin', 'marketing_user'];
    // return ['viewer'];
    return ['admin', 'marketing_user', 'analyst_user']; // Example: User has these roles
  };
  const currentUserRoles = getCurrentUserRoles();

  // --- DEFINE AVAILABLE QUICKBOARD PLUGINS ---
  const availableQuickBoardPlugins: QuickBoardPlugin[] = [
    {
      id: 'userCount',
      title: 'User Statistics',
      component: UserCountQuickBoardPlugin,
      roles: ['admin', 'analyst_user'], // Only admins and analysts see this
    },
    {
      id: 'manychatControl',
      title: 'ManyChat Messenger Control',
      component: ManyChatControlQuickBoardPlugin,
      roles: ['admin', 'marketing_user'], // Admins and marketing users
    },
    {
      id: 'supplierOverview',
      title: 'Supplier Overview',
      component: SupplierOverviewPlugin,
      roles: ['admin', 'procurement_user'], // Admins and procurement
    },
    // Add more plugins here
  ];

  const renderMainContent = ({
    activeSection,
    dashboardCards = clientDashboardCards,
    minimizedCards,
    maximizedCard,
    pinnedCards,
    toggleMinimizeCard,
    toggleMaximizeCard,
    togglePinCard,
    showCustomModal,
  }: RenderMainContentParams): ReactNode => {
    switch (activeSection) {
      case 'Overview':
        return initialDashboardContent;

      case 'Main Board':
        // ... (your existing Main Board logic - seems fine)
        if (maximizedCard !== null && dashboardCards.some(c => c.id === maximizedCard)) {
            const card = dashboardCards.find(c => c.id === maximizedCard);
            return ( <div className="bg-white rounded-lg shadow-xl p-4 sm:p-6 h-full flex flex-col"> {/* ... Maximized card UI ... */} <div>Maximized: {card?.title}</div></div> );
        }
        return ( <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"> {/* ... Grid of cards UI ... */} <div>Main Board Cards Here</div></div> );


      case 'Quick Board': // <<<--- THIS IS OUR TARGET SECTION
        return (
          <OriginalQuickBoardComponent
            showCustomModal={showCustomModal}
            plugins={availableQuickBoardPlugins} // Pass the defined plugins
            userRoles={currentUserRoles}        // Pass the current user's roles
          />
        );

      case 'My Account':
        return ( <div className="bg-white p-6 rounded-lg shadow"> <h2 className="text-xl font-semibold mb-4">My Client Account</h2> {/* ... */} </div> );
      case 'Notifications':
        return ( <div className="bg-white p-6 rounded-lg shadow"> <h2 className="text-xl font-semibold mb-4">All Client Notifications</h2> {/* ... */} </div> );
      case 'Settings':
        return ( <div className="bg-white p-6 rounded-lg shadow"> <h2 className="text-xl font-semibold mb-4">Client Application Settings</h2> {/* ... */} </div> );
      default:
        return ( <div className="flex items-center justify-center h-full text-lg text-gray-500"> Content for '{activeSection}' (Client) is not yet implemented. </div> );
    }
  };

  return (
    <BaseDashboardLayout
      tenant={tenant}
      tenantType={tenantType}
      navItems={navItems}
      dashboardCards={clientDashboardCards}
      initialNotifications={initialNotifications}
      renderMainContent={renderMainContent}
      initialActiveSection="Quick Board" // Set to "Quick Board" to test it by default
    />
  );
}